// Client must send: Accept: application/xml
// Controller returns same DTO — formatter selection changes output shape

public sealed class CsvOutputFormatter : TextOutputFormatter
{
    public CsvOutputFormatter()
    {
        SupportedMediaTypes.Add(MediaTypeHeaderValue.Parse("text/csv"));
        SupportedEncodings.Add(Encoding.UTF8);
    }

    protected override bool CanWriteType(Type? type)
        => type != null && typeof(IEnumerable<OrderDto>).IsAssignableFrom(type);

    public override async Task WriteResponseBodyAsync(
        OutputFormatterWriteContext context, Encoding encoding)
    {
        var items = (IEnumerable<OrderDto>)context.Object!;
        var writer = context.HttpContext.Response.BodyWriter.AsStream();
        await writer.WriteAsync(Encoding.UTF8.GetBytes("id\n"));
        foreach (var o in items)
            await writer.WriteAsync(Encoding.UTF8.GetBytes($"{o.Id}\n"));
    }
}

builder.Services.AddControllers(o =>
    o.OutputFormatters.Add(new CsvOutputFormatter()));
